    public Object parseTrade(Object trade, Map<String, Object> market)
    {
        //
        // fetchTrades
        //
        //  spot:
        //
        //     {
        //         "id" : "60014521",
        //         "price" : "23162.94",
        //         "quantity" : "0.00009",
        //         "amount" : "2.0846646",
        //         "takerSide" : "SELL",
        //         "ts" : 1659684602042,
        //         "createTime" : 1659684602036
        //     }
        //
        //   swap:
        //
        //     {
        //         "id": "105807376",
        //         "side": "buy",
        //         "px": "84410.57",
        //         "qty": "1",
        //         "amt": "84.41057",
        //         "cT": "1740777563557",
        //     }
        //
        // fetchMyTrades
        //
        //  spot:
        //
        //     {
        //         "id": "32164924331503616",
        //         "symbol": "LINK_USDT",
        //         "accountType": "SPOT",
        //         "orderId": "32164923987566592",
        //         "side": "SELL",
        //         "type": "MARKET",
        //         "matchRole": "TAKER",
        //         "createTime": 1648635115525,
        //         "price": "11",
        //         "quantity": "0.5",
        //         "amount": "5.5",
        //         "feeCurrency": "USDT",
        //         "feeAmount": "0.007975",
        //         "pageId": "32164924331503616",
        //         "clientOrderId": "myOwnId-321"
        //     }
        //
        //  swap:
        //
        //     {
        //         "symbol": "BTC_USDT_PERP",
        //         "trdId": "105813553",
        //         "side": "SELL",
        //         "type": "TRADE",
        //         "mgnMode": "CROSS",
        //         "ordType": "MARKET",
        //         "clOrdId": "polo418912106147315112",
        //         "role": "TAKER",
        //         "px": "84704.9",
        //         "qty": "1",
        //         "cTime": "1740842829430",
        //         "uTime": "1740842829450",
        //         "feeCcy": "USDT",
        //         "feeAmt": "0.04235245",
        //         "deductCcy": "",
        //         "deductAmt": "0",
        //         "feeRate": "0.0005",
        //         "id": "418912106342654592",
        //         "posSide": "BOTH",
        //         "ordId": "418912106147315112",
        //         "qCcy": "USDT",
        //         "value": "84.7049",
        //         "actType": "TRADING"
        //     },
        //
        // fetchOrderTrades (taker trades)
        //
        //     {
        //         "id": "30341456333942784",
        //         "symbol": "LINK_USDT",
        //         "accountType": "SPOT",
        //         "orderId": "30249408733945856",
        //         "side": "BUY",
        //         "type": "LIMIT",
        //         "matchRole": "MAKER",
        //         "createTime": 1648200366864,
        //         "price": "3.1",
        //         "quantity": "1",
        //         "amount": "3.1",
        //         "feeCurrency": "LINK",
        //         "feeAmount": "0.00145",
        //         "pageId": "30341456333942784",
        //         "clientOrderId": ""
        //     }
        //
        String id = this.safeStringN(trade, new ArrayList<Object>(Arrays.asList("id", "tradeID", "trdId")));
        String orderId = this.safeString2(trade, "orderId", "ordId");
        Long timestamp = this.safeIntegerN(trade, new ArrayList<Object>(Arrays.asList("ts", "createTime", "cT", "cTime")));
        String marketId = this.safeString(trade, "symbol");
        Map<String, Object> marketResolved = (Map<String, Object>) this.safeMarket(marketId, market, "_", (String) null);
        String symbol = (String) ((Map<String, Object>)marketResolved).get("symbol");
        String side = this.safeStringLower2(trade, "side", "takerSide");
        Map<String, Object> fee = null;
        String priceString = this.safeString2(trade, "price", "px");
        String amountString = this.safeString2(trade, "quantity", "qty");
        String costString = this.safeString2(trade, "amount", "amt");
        String feeCurrencyId = this.safeString2(trade, "feeCurrency", "feeCcy");
        String feeCostString = this.safeString2(trade, "feeAmount", "feeAmt");
        if (!java.util.Objects.equals(feeCostString, null))
        {
            String feeCurrencyCode = this.safeCurrencyCode(feeCurrencyId, (Map<String, Object>) null);
            fee = Helpers.newMap(
                "cost", feeCostString,
                "currency", feeCurrencyCode
            );
        }
        return this.safeTrade(Helpers.newMap(
            "id", id,
            "info", trade,
            "timestamp", timestamp,
            "datetime", this.iso8601(timestamp),
            "symbol", symbol,
            "order", orderId,
            "type", this.safeStringLower2(trade, "ordType", "type"),
            "side", side,
            "takerOrMaker", this.safeStringLower2(trade, "matchRole", "role"),
            "price", priceString,
            "amount", amountString,
            "cost", costString,
            "fee", fee
        ), Helpers.toMapArg(marketResolved));
    }

